//! `os.lazy.bt.v1` (`idl/bt.midl`, docs/bluetooth-plan.md B5): the Bluetooth
//! device list, discovery and pairing `btd` serves to the person at the
//! machine.
//!
//! The stubs are generated by `midlc`; this module adds the service name, the
//! parcel framing for `btd`'s server loop, and a blocking [`Client`] with the
//! event decoder for clients that are Rust programs (the Settings pane's
//! platform layer). `btctl` is a Rhai script and calls the same methods
//! through the `msg` module. Failures come back as the shared structured
//! error field. No method returns a key.

use alloc::vec::Vec;

use libmessenger::{flags, Header, Object, Parcel, VERSION};

use super::services::{error_field, refusal};
use super::{create_pair, registry, Endpoint, Error, Message, Result};

/// The generated stubs.
pub use messenger_generated::os_lazy_bt_v1 as wire;

pub use wire::{Device, Pairing};

/// The name `btd` registers.
pub const NAME: &str = "os.lazy.bt";

/// The interface id every parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// Subscribers `btd` serves at once.
pub const MAX_SUBSCRIBERS: usize = 4;

/// A parcel of `method` carrying an encoded `body` and its `objects`.
pub fn parcel(method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: INTERFACE,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A one-way event parcel (`DeviceEvent`, `PairingEvent`).
pub fn event(method: u32, body: Vec<u8>) -> Parcel {
    let mut parcel = parcel(method, body, Vec::new());
    parcel.header.flags = flags::ONE_WAY;
    parcel
}

/// A structured refusal of `method`: the positive errno `code` and a short,
/// non-secret reason.
pub fn error_reply(method: u32, code: i64, text: &str) -> Parcel {
    refusal(INTERFACE, method, code, text)
}

/// What a subscriber receives.
#[derive(Clone, Debug, PartialEq)]
pub enum Event {
    Device { kind: u32, device: Device },
    Pairing(Pairing),
}

/// Decode an event message; `None` for anything that is not one of ours (a
/// stranger may write to the endpoint a subscriber hands over).
pub fn decode_event(message: &Message) -> Option<Event> {
    if message.interface_id() != INTERFACE {
        return None;
    }
    let body = &message.parcel.body;
    match message.method() {
        wire::METHOD_DEVICEEVENT => {
            let args = wire::decode_device_event_args(body).ok()?;
            Some(Event::Device {
                kind: args.kind,
                device: args.device,
            })
        }
        wire::METHOD_PAIRINGEVENT => Some(Event::Pairing(
            wire::decode_pairing_event_args(body).ok()?.pairing,
        )),
        _ => None,
    }
}

/// A blocking client of `btd`.
pub struct Client {
    endpoint: Endpoint,
}

impl Client {
    /// Resolve [`NAME`]: `ENOENT` while `btd` is not serving.
    pub fn connect() -> Result<Client> {
        Ok(Client {
            endpoint: registry::resolve(NAME)?,
        })
    }

    /// Give up the handle: it was obtained by name, so it is released, not
    /// closed (closing would end `btd`'s service side).
    pub fn release(self) {
        let _ = self.endpoint.release();
    }

    fn call(&self, method: u32, body: Vec<u8>, objects: Vec<Object>) -> Result<Parcel> {
        let reply = self.endpoint.call(&parcel(method, body, objects), None)?;
        match error_field(&reply)? {
            Some(code) => Err(Error::Errno(-code)),
            None => Ok(reply),
        }
    }

    pub fn list(&self) -> Result<wire::ListReply> {
        let reply = self.call(wire::METHOD_LIST, Vec::new(), Vec::new())?;
        wire::decode_list_reply(&reply.body).map_err(Error::Parcel)
    }

    pub fn status(&self) -> Result<Pairing> {
        let reply = self.call(wire::METHOD_STATUS, Vec::new(), Vec::new())?;
        Ok(wire::decode_status_reply(&reply.body)
            .map_err(Error::Parcel)?
            .pairing)
    }

    pub fn start_discovery(&self, seconds: u32) -> Result<()> {
        let body = wire::encode_start_discovery_args(&wire::StartDiscoveryArgs { seconds })
            .map_err(Error::Parcel)?;
        self.call(wire::METHOD_STARTDISCOVERY, body, Vec::new())
            .map(|_| ())
    }

    pub fn stop_discovery(&self) -> Result<()> {
        self.call(wire::METHOD_STOPDISCOVERY, Vec::new(), Vec::new())
            .map(|_| ())
    }

    pub fn pair(&self, address: &str) -> Result<()> {
        let body = wire::encode_pair_args(&wire::PairArgs {
            address: address.into(),
        })
        .map_err(Error::Parcel)?;
        self.call(wire::METHOD_PAIR, body, Vec::new()).map(|_| ())
    }

    pub fn confirm_number(&self, address: &str, accept: bool) -> Result<()> {
        let body = wire::encode_confirm_number_args(&wire::ConfirmNumberArgs {
            address: address.into(),
            accept,
        })
        .map_err(Error::Parcel)?;
        self.call(wire::METHOD_CONFIRMNUMBER, body, Vec::new())
            .map(|_| ())
    }

    pub fn cancel_pairing(&self) -> Result<()> {
        self.call(wire::METHOD_CANCELPAIRING, Vec::new(), Vec::new())
            .map(|_| ())
    }

    pub fn forget(&self, address: &str) -> Result<()> {
        let body = wire::encode_forget_args(&wire::ForgetArgs {
            address: address.into(),
        })
        .map_err(Error::Parcel)?;
        self.call(wire::METHOD_FORGET, body, Vec::new()).map(|_| ())
    }

    /// Subscribe: returns the endpoint events arrive on (the far end moved to
    /// `btd`). Close it to unsubscribe.
    pub fn subscribe(&self) -> Result<Endpoint> {
        let (mine, theirs) = create_pair()?;
        let result = wire::encode_subscribe_args(&wire::SubscribeArgs {
            events: theirs.handle(),
        })
        .map_err(Error::Parcel)
        .and_then(|(body, objects)| self.call(wire::METHOD_SUBSCRIBE, body, objects));
        match result {
            Ok(_) => Ok(mine),
            Err(error) => {
                let _ = mine.close();
                let _ = theirs.close();
                Err(error)
            }
        }
    }
}
